import{_ as n,C as c,o as t,c as r,a6 as o,b as i,w as d,a as s,E as l,af as h}from"./chunks/framework.DIp0zHSV.js";const w=JSON.parse('{"title":"Action Handler","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/subsystems/action-handler.md","filePath":"architecture/subsystems/action-handler.md","lastUpdated":1794368910000}'),u={name:"architecture/subsystems/action-handler.md"};function p(m,e,g,f,v,A){const a=c("Mermaid");return t(),r("div",null,[e[1]||(e[1]=o('<h1 id="action-handler" tabindex="-1">Action Handler <a class="header-anchor" href="#action-handler" aria-label="Permalink to &quot;Action Handler&quot;">​</a></h1><blockquote><p><strong>Per card (<code>card._actionHandler</code>)</strong>: Gesture listeners, Home Assistant action dispatch, card sounds and animation triggers for card elements.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>LCARdSActionHandler</code> (<code>src/base/LCARdSActionHandler.js</code>) turns a card&#39;s <code>tap_action</code>, <code>hold_action</code> and <code>double_tap_action</code> into event listeners on an element. For each gesture it fires the matching animation trigger (with the pointer position), plays the card sound and runs the configured action. It is a plain class (not a <code>BaseService</code>) and receives no HASS from the core: every call is given the HASS to act with.</p><h3 id="instances" tabindex="-1">Instances <a class="header-anchor" href="#instances" aria-label="Permalink to &quot;Instances&quot;">​</a></h3><p>Every <code>LCARdSCard</code> creates its own handler in its constructor (<code>this._actionHandler = new LCARdSActionHandler()</code>, <code>src/base/LCARdSCard.js</code>). <code>LCARdSCard.setupActions()</code>, segment actions, the elbow&#39;s segment handlers, the button&#39;s segment <code>runAction()</code> calls and the astrometrics card&#39;s <code>runAction()</code> calls all go through <code>this._actionHandler</code>. The class keeps no state of its own: everything a <code>setupActions()</code> call needs lives in its closure, and the returned cleanup removes the listeners.</p><p>There is no page-wide handler. A core singleton (<code>window.lcards.core.actionHandler</code>, also handed to cards as <code>_singletons.actionHandler</code>) came with the unified action handling of ed2436d8 (2025-11-08), but that same work moved <code>setupActions()</code> to the per-card instance, so nothing used it; it was removed in 2026.11 with its debug entry.</p><hr><h2 id="module-exports" tabindex="-1">Module Exports <a class="header-anchor" href="#module-exports" aria-label="Permalink to &quot;Module Exports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Export</th><th>Description</th></tr></thead><tbody><tr><td><code>LCARdSActionHandler</code></td><td>The class</td></tr><tr><td><code>TOGGLE_OFF_STATES</code></td><td><code>[&#39;closed&#39;, &#39;locked&#39;, &#39;off&#39;]</code>: states a toggle turns <strong>on</strong> from (Home Assistant&#39;s <code>STATES_OFF</code>); any other state turns off</td></tr><tr><td><code>SPECIAL_TOGGLE_ACTIONS</code></td><td>Domains whose toggle is not <code>turn_on</code> / <code>turn_off</code> (Home Assistant&#39;s <code>SPECIAL_TOGGLE_ACTIONS</code>): <code>button</code> and <code>input_button</code> press, <code>cover</code> opens/closes, <code>lock</code> unlocks/locks, <code>valve</code> opens/closes, <code>scene</code> turns on both ways, and so on</td></tr><tr><td><code>toggleService(entityId, state)</code></td><td><code>{ domain, service }</code> a toggle calls, chosen from the state and domain like Home Assistant&#39;s own toggle; a <code>group</code> goes through the <code>homeassistant</code> domain; with no known state, the domain&#39;s <code>toggle</code> service</td></tr><tr><td><code>actionSoundEvent(actionConfig, state, fallback)</code></td><td>The sound event for a gesture: <code>toggle_on</code> / <code>toggle_off</code> for a toggle with a known state, <code>fallback</code> (e.g. <code>card_tap</code>) for other actions, <code>null</code> for no action or <code>action: none</code>. Used by the button card&#39;s segments</td></tr><tr><td><code>pointerOf(event)</code></td><td><code>{ clientX, clientY }</code> of a mouse, pointer or touch event (first touch, or first changed touch), or <code>null</code> for a keyboard activation (a click at 0,0 with <code>detail === 0</code>) or a non-finite position. Also used by the data grid</td></tr></tbody></table><hr><h2 id="setupactions-element-actions-hass-options-→-cleanup" tabindex="-1"><code>setupActions(element, actions, hass, options) → cleanup</code> <a class="header-anchor" href="#setupactions-element-actions-hass-options-→-cleanup" aria-label="Permalink to &quot;`setupActions(element, actions, hass, options) → cleanup`&quot;">​</a></h2><p>Attaches the listeners and returns a function that removes them. With no <code>element</code> it returns a no-op.</p><p>Cards call the <code>LCARdSCard.setupActions(element, actions, options)</code> wrapper rather than the handler directly. The wrapper adds <code>animations: this.config.animations</code>, <code>getAnimationSetup</code>, <code>shadowRoot</code>, <code>entity</code> (the caller&#39;s, else <code>config.entity</code>), <code>getHass: () =&gt; this.hass</code> and the card&#39;s <code>sounds:</code> overrides as <code>soundOverride</code> (<code>_cardSoundOverride()</code>).</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>elementId</code></td><td>ID used for animation targeting; falls back to <code>element.id</code>, then the <code>data-overlay-id</code> attribute. Without one, no animation triggers fire and no hover listeners are attached</td></tr><tr><td><code>animationManager</code></td><td>When given (with an <code>elementId</code>), the overlay&#39;s animation scope is registered at once</td></tr><tr><td><code>getAnimationManager</code></td><td>Getter used at gesture time and for late binding; falls back to <code>window.lcards.core.getAnimationManager()</code></td></tr><tr><td><code>animations</code></td><td>Animation configs registered on the scope</td></tr><tr><td><code>getAnimationSetup</code></td><td>Returns <code>{ overlayId, elementSelector }</code>; <code>elementSelector</code> (default <code>[data-overlay-id]</code>) picks the animation target inside <code>shadowRoot</code></td></tr><tr><td><code>shadowRoot</code></td><td>Where <code>elementSelector</code> is looked up; the element itself otherwise</td></tr><tr><td><code>entity</code></td><td>Default entity for actions that name none</td></tr><tr><td><code>getHass</code></td><td>Returns the card&#39;s current HASS at action time (a handler set up once, such as a data grid cell, must not act on the states it was set up with); falls back to the <code>hass</code> argument</td></tr><tr><td><code>soundOverride</code></td><td><code>{ [soundEvent]: assetKey | null }</code>; <code>null</code> silences that event</td></tr><tr><td><code>disableHover</code></td><td>No pointer cursor and no hover / leave listeners (non-interactive cards, elbow segments)</td></tr><tr><td><code>segmentsOwnHold</code></td><td>A hold that starts inside a <code>[data-lcards-segment]</code> child is left to that segment&#39;s own handler</td></tr></tbody></table><h3 id="animation-scope" tabindex="-1">Animation scope <a class="header-anchor" href="#animation-scope" aria-label="Permalink to &quot;Animation scope&quot;">​</a></h3><p>With an <code>elementId</code> and an <code>animationManager</code>, <code>setupActions()</code> always calls <code>animationManager.onOverlayRendered(overlayId, targetElement, { animations })</code>, even with no animations, so rule-triggered animations have a scope to run in. <code>overlayId</code> is the explicit <code>elementId</code> (so several handlers on one card, like the slider&#39;s four border sides, do not overwrite each other&#39;s scope), else <code>getAnimationSetup().overlayId</code>.</p><p>Without an <code>animationManager</code> but with <code>animations</code>, the setup is kept as pending. The first gesture then runs <code>ensureAnimationsRegistered()</code>: it resolves the manager through <code>getAnimationManager()</code> or the core, creates the scope (<code>createScopeForOverlay()</code>), a <code>TriggerManager</code>, registers each animation with <code>registerAnimation()</code> and calls <code>triggerManager.finalizeRegistrations()</code> once the whole batch is registered.</p><h3 id="gestures" tabindex="-1">Gestures <a class="header-anchor" href="#gestures" aria-label="Permalink to &quot;Gestures&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Gesture</th><th>Listener</th><th>Behaviour</th></tr></thead><tbody><tr><td>Tap</td><td><code>click</code> (capture)</td><td>Ignored when the click came from inside a <code>[data-lcards-segment]</code> child (the segment handles it) or right after a completed hold. Otherwise <code>stopPropagation()</code> and <code>preventDefault()</code>. With no <code>double_tap_action</code>, runs at once</td></tr><tr><td>Double tap</td><td>same <code>click</code> listener</td><td>With a <code>double_tap_action</code>, the first click waits 300 ms: a second click inside that window runs the double tap at once; otherwise the single tap runs (only if there is a <code>tap_action</code>). <code>dblclick</code> is not used: it is unreliable on touch devices</td></tr><tr><td>Hold</td><td><code>pointerdown</code> (capture), ended by <code>pointerup</code>, <code>pointercancel</code>, <code>pointerleave</code></td><td>Runs after 500 ms held; releasing earlier cancels it. A completed hold blocks the click that follows</td></tr><tr><td>Hover</td><td><code>mouseenter</code> (capture)</td><td>Desktop only (<code>(hover: hover) and (pointer: fine)</code>), needs an <code>elementId</code>, not with <code>disableHover</code></td></tr><tr><td>Leave</td><td><code>mouseleave</code> (capture)</td><td>Same conditions; stops running <code>on_hover</code> animations, then fires <code>on_leave</code></td></tr></tbody></table><p>When there is at least one action and <code>disableHover</code> is not set, the element gets <code>cursor: pointer</code>. The element also gets <code>data-lcards-actions-attached=&quot;true&quot;</code> and <code>data-lcards-handler-count</code>; cleanup removes them.</p><h3 id="what-one-gesture-does" tabindex="-1">What one gesture does <a class="header-anchor" href="#what-one-gesture-does" aria-label="Permalink to &quot;What one gesture does&quot;">​</a></h3>',23)),(t(),i(h,null,{default:d(()=>[l(a,{id:"mermaid-292",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20U%20as%20User%0A%20%20%20%20participant%20AH%20as%20setupActions%20listener%0A%20%20%20%20participant%20AM%20as%20AnimationManager%0A%20%20%20%20participant%20SM%20as%20SoundManager%0A%20%20%20%20participant%20HA%20as%20Home%20Assistant%0A%0A%20%20%20%20U-%3E%3EAH%3A%20click%20%2F%20held%20500%20ms%20%2F%20mouseenter%0A%20%20%20%20AH-%3E%3EAH%3A%20ensureAnimationsRegistered()%20(late%20binding%2C%20once)%0A%20%20%20%20AH-%3E%3EAM%3A%20triggerAnimations(elementId%2C%20trigger%2C%20pointer%20context)%0A%20%20%20%20AH-%3E%3ESM%3A%20play(soundEvent%2C%20cardOverride%20if%20set)%0A%20%20%20%20AH-%3E%3EAH%3A%20_executeAction(actionConfig%2C%20getHass()%2C%20element%2C%20entity)%0A%20%20%20%20AH-%3E%3EHA%3A%20callService%20%2F%20hass-more-info%20%2F%20navigate%20%2F%20...%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>Hover differs: it fires <code>on_hover</code> without a pointer context, plays <code>card_hover</code>, and runs no action.</p><hr><h2 id="sound-hooks" tabindex="-1">Sound Hooks <a class="header-anchor" href="#sound-hooks" aria-label="Permalink to &quot;Sound Hooks&quot;">​</a></h2><p>The handler plays through <code>window.lcards.core.soundManager.play(eventType)</code>, or <code>play(eventType, { cardOverride })</code> when <code>soundOverride</code> has the event (<code>null</code> silences it, a string plays that asset).</p><table tabindex="0"><thead><tr><th>Gesture</th><th>Sound event</th></tr></thead><tbody><tr><td>Tap</td><td><code>card_tap</code></td></tr><tr><td>Double tap</td><td><code>card_double_tap</code></td></tr><tr><td>Hold</td><td><code>card_hold</code></td></tr><tr><td>Any of those with <code>action: toggle</code> and a known entity state</td><td><code>toggle_on</code> when the state is in <code>TOGGLE_OFF_STATES</code>, else <code>toggle_off</code> (replaces the gesture&#39;s event)</td></tr><tr><td>Hover</td><td><code>card_hover</code></td></tr></tbody></table><p>A gesture whose action is missing or <code>action: none</code> plays nothing. <code>LCARdSCard._cardSoundOverride()</code> builds <code>soundOverride</code> from the card&#39;s <code>sounds:</code> block: <code>sounds.enabled: false</code> silences all six events, otherwise each event key present is passed on.</p><hr><h2 id="pointer-context" tabindex="-1">Pointer Context <a class="header-anchor" href="#pointer-context" aria-label="Permalink to &quot;Pointer Context&quot;">​</a></h2><p>Tap, double tap and hold capture <code>{ pointer: pointerOf(event) }</code> from the triggering event (for a hold, the <code>pointerdown</code>) and pass it to <code>animationManager.triggerAnimations(elementId, trigger, context)</code>, which hands it to <code>playAnimation()</code>. Stagger animations with <code>from: &#39;pointer&#39;</code> (the tap-ripple) start at that point. A keyboard activation gives <code>pointer: null</code>.</p><hr><h2 id="action-dispatch" tabindex="-1">Action Dispatch <a class="header-anchor" href="#action-dispatch" aria-label="Permalink to &quot;Action Dispatch&quot;">​</a></h2><p><code>_executeAction(actionConfig, hass, element, defaultEntity)</code> does nothing without an <code>actionConfig</code> or HASS. The entity is <code>actionConfig.entity</code>, else <code>defaultEntity</code>, else <code>element.dataset.entity</code>.</p><table tabindex="0"><thead><tr><th><code>action</code></th><th>What happens</th></tr></thead><tbody><tr><td><code>toggle</code></td><td><code>toggleService(entityId, state)</code>, then <code>hass.callService(domain, service, { entity_id })</code>. Needs an entity</td></tr><tr><td><code>more-info</code></td><td>Dispatches <code>hass-more-info</code> (<code>{ entityId }</code>, bubbling and composed) from the element, or the document. Needs an entity</td></tr><tr><td><code>call-service</code>, <code>perform-action</code></td><td>Service from <code>perform_action</code>, else the older <code>service</code> (<code>domain.service</code>); data from <code>data</code>, else <code>service_data</code>; <code>hass.callService(domain, service, data, target)</code>, the target passed separately as Home Assistant&#39;s <code>handle-action</code> does. The older names log at debug level</td></tr><tr><td><code>fire-dom-event</code></td><td>Dispatches <code>ll-custom</code> (the action config as <code>detail</code>, bubbling and composed) from the element, as Home Assistant does; browser_mod listens for it</td></tr><tr><td><code>navigate</code></td><td><code>history.pushState(null, &#39;&#39;, navigation_path)</code> and a <code>location-changed</code> window event</td></tr><tr><td><code>url</code></td><td><code>window.open(url_path, &#39;_blank&#39;)</code></td></tr><tr><td><code>assist</code></td><td>Dispatches <code>show-dialog</code> for <code>ha-voice-command-dialog</code> with <code>pipeline_id</code> (default <code>preferred</code>) and <code>start_listening</code> (default <code>true</code>)</td></tr><tr><td><code>fly-to</code></td><td><code>window.lcards.cards.astrometrics.flyTo(card, { point } or { view }, { duration, warp })</code></td></tr><tr><td><code>set-clock</code></td><td><code>window.lcards.cards.astrometrics.setClock(card, { date, rate })</code></td></tr><tr><td><code>set-model-scale</code></td><td><code>window.lcards.cards.astrometrics.setModelScale(card, model_scale ?? &#39;toggle&#39;)</code></td></tr><tr><td><code>none</code></td><td>Nothing</td></tr><tr><td>anything else</td><td>Logged as a warning</td></tr></tbody></table><p>The user-facing action reference is <a href="./../../core/actions.html">Actions</a>.</p><h3 id="runaction-actionconfig-hass-element-defaultentity" tabindex="-1"><code>runAction(actionConfig, hass, element, defaultEntity?)</code> <a class="header-anchor" href="#runaction-actionconfig-hass-element-defaultentity" aria-label="Permalink to &quot;`runAction(actionConfig, hass, element, defaultEntity?)`&quot;">​</a></h3><p>Runs one action now, for things that are not elements with listeners: an astrometrics point picked on the canvas, a button segment. It first checks <code>_validateActionConfig()</code> (an <code>action</code> is required; <code>call-service</code> / <code>perform-action</code> need a service, <code>navigate</code> a <code>navigation_path</code>, <code>url</code> a <code>url_path</code>, the astrometrics actions a <code>card</code> plus their target) and then calls <code>_executeAction()</code>. It plays no sound and fires no animation: the caller does that. The listener path of <code>setupActions()</code> does not run this validation; the individual handlers log a warning and return when a required field is missing.</p><hr><h2 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h2><p>A card&#39;s handler is <code>card._actionHandler</code> (for instance <code>document.querySelector(&#39;lcards-button&#39;)._actionHandler</code> on a page without shadow roots in the way). It has no debug snapshot; to see whether an element has listeners, look for <code>data-lcards-actions-attached</code> on it.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./animation-manager.html">Animation Manager</a></li><li><a href="./sound-system.html">Sound System</a></li><li><a href="./rules-engine.html">Rules Engine</a></li><li><a href="./../../core/actions.html">Actions (user guide)</a></li><li><a href="./../cards/lcards-card-foundation.html">Card foundation</a></li></ul>',22))])}const _=n(u,[["render",p]]);export{w as __pageData,_ as default};
